import { isValidNumber } from '@zcatalyst/utils';
import { CatalystNoSQLError } from '../utils/error';
import { NoSQLByte } from './byte';
export class NoSQLStringSet extends Set {
    constructor(values) {
        super(values);
    }
    add(str) {
        if (typeof str !== 'string') {
            throw new Error('str value not a string');
        }
        super.add(str);
        return this;
    }
    toJSON() {
        return Array.from(this);
    }
}
export class NoSQLNumberSet extends Set {
    constructor(values) {
        super(values);
    }
    add(num) {
        if (typeof num === 'number') {
            isValidNumber(num);
        }
        else if (typeof num !== 'bigint') {
            throw new CatalystNoSQLError('not_number', `The value of num is not a valid number type`);
        }
        super.add(num);
        return this;
    }
    toJSON() {
        return Array.from(this).map((val) => val.toString());
    }
}
export class NoSQLByteSet extends Set {
    constructor(values) {
        super(values?.map((val) => (val instanceof NoSQLByte ? val : new NoSQLByte(val))));
    }
    add(buffer) {
        super.add(buffer instanceof NoSQLByte ? buffer : new NoSQLByte(buffer));
        return this;
    }
    toJSON() {
        return Array.from(this);
    }
}
